head.b:skin:
:root{
  --ink:#252724;
  --muted:#6d7069;
  --paper:#fbfaf7;
  --surface:#ffffff;
  --soft:#f2eee7;
  --line:#e6e0d7;
  --accent:#b45336;
  --accent-dark:#823720;
  --max:1160px;
  --radius:20px
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:var(--paper);color:var(--ink);font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.7}
a{color:var(--accent-dark);text-underline-offset:3px}
a:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid var(--accent);outline-offset:3px}
img{max-width:100%;height:auto}
.skip-link{position:absolute;left:-9999px;top:12px;z-index:1000;background:var(--ink);color:#fff;padding:10px 14px;border-radius:8px}
.skip-link:focus{left:12px}
.site-header{background:rgba(251,250,247,.97);border-bottom:1px solid var(--line)}
.header-inner{max-width:var(--max);margin:0 auto;padding:20px 24px;display:flex;align-items:center;justify-content:space-between;gap:28px}
.brand{min-width:0;max-width:620px;display:block;color:var(--ink);text-decoration:none}
.brand-name{display:block;font-family:Georgia,'Times New Roman',serif;font-size:1.65rem;font-weight:700;line-height:1.2;letter-spacing:-.035em;overflow-wrap:anywhere}
.brand-description{display:block;margin-top:5px;color:var(--muted);font-size:.88rem;line-height:1.45}
.nav{display:flex;align-items:center;justify-content:flex-end;gap:18px;flex-wrap:wrap}
.nav a{font-size:.9rem;font-weight:700;text-decoration:none;color:var(--ink)}
.nav a:hover{color:var(--accent)}
.page-shell{max-width:var(--max);margin:0 auto;padding:24px 24px 64px}
.home-intro{padding:clamp(28px,5vw,58px);margin:8px 0 44px;background:linear-gradient(135deg,#f3eee7 0%,#fbfaf7 80%);border:1px solid var(--line);border-radius:var(--radius)}
.eyebrow{margin:0 0 12px;color:var(--accent-dark);font-size:.75rem;letter-spacing:.16em;text-transform:uppercase;font-weight:800}
.home-intro h1{max-width:850px;margin:0;font-family:Georgia,'Times New Roman',serif;font-size:clamp(2.3rem,5.6vw,4.5rem);font-weight:700;line-height:1.03;letter-spacing:-.055em;overflow-wrap:anywhere}
.home-description{max-width:780px;margin:20px 0 0;color:#55574f;font-size:1.08rem;line-height:1.8}
.posts-section{margin:0}
.section-heading{display:flex;align-items:end;justify-content:space-between;gap:18px;margin:0 0 22px;padding-bottom:15px;border-bottom:1px solid var(--line)}
.section-heading h1,.section-heading h2{margin:0;font-family:Georgia,'Times New Roman',serif;font-size:clamp(1.65rem,3vw,2.35rem);line-height:1.18;letter-spacing:-.035em;overflow-wrap:anywhere}
.section-heading p{max-width:360px;margin:0;color:var(--muted);font-size:.9rem;text-align:right}
.posts-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}
.post-card{display:flex;flex-direction:column;min-width:0;overflow:hidden;background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);transition:transform .18s ease,box-shadow .18s ease}
.post-card:hover{transform:translateY(-3px);box-shadow:0 14px 32px rgba(38,31,23,.08)}
.post-card-image{display:flex;align-items:center;justify-content:center;aspect-ratio:16/10;overflow:hidden;background:var(--soft);color:var(--accent-dark);text-decoration:none}
.post-card-image img{display:block;width:100%;height:100%;object-fit:cover}
.post-card-image.no-image{padding:18px;font-family:Georgia,'Times New Roman',serif;font-size:1.1rem;font-weight:700;text-align:center}
.post-card-content{display:flex;flex:1;flex-direction:column;padding:22px}
.post-meta{margin:0 0 10px;color:var(--muted);font-size:.79rem;letter-spacing:.02em}
.post-card h2,.post-card h3{margin:0 0 12px;font-family:Georgia,'Times New Roman',serif;font-size:1.35rem;line-height:1.3;letter-spacing:-.025em;overflow-wrap:anywhere}
.post-card h2 a,.post-card h3 a{color:var(--ink);text-decoration:none}
.post-card h2 a:hover,.post-card h3 a:hover{color:var(--accent-dark)}
.post-excerpt{margin:0 0 20px;color:#5c5e57;font-size:.95rem;line-height:1.7}
.read-more{display:inline-flex;align-items:center;gap:8px;margin-top:auto;width:max-content;font-size:.9rem;font-weight:800;text-decoration:none}
.read-more:hover{text-decoration:underline}
.blog-pager{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;margin:34px 0 0}
.pager-link{display:inline-block;padding:10px 14px;border:1px solid var(--line);border-radius:10px;background:#fff;text-decoration:none;font-weight:700;font-size:.9rem}
.pager-link:hover{border-color:var(--accent);color:var(--accent-dark)}
.empty-state{padding:28px;background:#fff;border:1px dashed #d4c8ba;border-radius:14px;color:var(--muted)}
.article-page{max-width:850px;margin:10px auto 0;padding:clamp(24px,5vw,58px);background:#fff;border:1px solid var(--line);border-radius:var(--radius)}
.article-header{margin:0 0 30px;padding-bottom:24px;border-bottom:1px solid var(--line)}
.article-header .post-meta{margin-bottom:12px}
.article-header h1{margin:0;font-family:Georgia,'Times New Roman',serif;font-size:clamp(2.2rem,5vw,3.8rem);line-height:1.08;letter-spacing:-.05em;overflow-wrap:anywhere}
.article-content{color:#30322d;font-size:1.06rem;line-height:1.9;overflow-wrap:anywhere}
.article-content h2{margin:2.2em 0 .7em;font-family:Georgia,'Times New Roman',serif;font-size:clamp(1.55rem,3vw,2.1rem);line-height:1.2;letter-spacing:-.03em}
.article-content h3{margin:1.8em 0 .6em;font-family:Georgia,'Times New Roman',serif;font-size:1.35rem;line-height:1.3}
.article-content p{margin:0 0 1.35em}
.article-content ul,.article-content ol{padding-left:1.5rem;margin:0 0 1.5em}
.article-content li{margin:.35em 0}
.article-content img{display:block;max-width:100%;height:auto;margin:1.5em auto;border-radius:12px}
.article-content figure{max-width:100%;margin:1.6em 0}
.article-content figcaption{color:var(--muted);font-size:.85rem;text-align:center}
.article-content blockquote{margin:1.6em 0;padding:12px 20px;border-left:4px solid var(--accent);background:var(--soft);color:#4d4e47}
.article-content table{display:block;max-width:100%;overflow-x:auto;border-collapse:collapse}
.article-content th,.article-content td{padding:10px 12px;border:1px solid var(--line);text-align:left}
.article-content pre{max-width:100%;overflow-x:auto;padding:16px;background:#f4f1eb;border-radius:10px}
.article-content iframe{max-width:100%}
.article-footer{margin-top:36px;padding-top:20px;border-top:1px solid var(--line)}
.article-footer a{font-weight:800;text-decoration:none}
.article-footer a:hover{text-decoration:underline}
.site-footer{background:#262722;color:#f8f5ef}
.footer-inner{max-width:var(--max);margin:0 auto;padding:34px 24px 40px}
.footer-title{font-family:Georgia,'Times New Roman',serif;font-size:1.35rem;font-weight:700}
.footer-links{display:flex;gap:16px;flex-wrap:wrap;margin:15px 0}
.footer-links a{color:#f8f5ef;text-decoration:none;font-size:.88rem}
.footer-links a:hover{text-decoration:underline}
.footer-note{max-width:850px;color:#d4d1c9;font-size:.82rem;line-height:1.7}
@media(max-width:900px){
  .header-inner{align-items:flex-start;flex-direction:column;gap:16px}
  .nav{justify-content:flex-start;gap:12px 18px}
  .posts-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .section-heading{align-items:flex-start;flex-direction:column}
  .section-heading p{text-align:left}
}
@media(max-width:600px){
  body{font-size:15px}
  .header-inner{padding:17px 18px}
  .brand-name{font-size:1.45rem}
  .page-shell{padding:16px 16px 42px}
  .home-intro{margin:4px 0 30px;padding:28px 22px}
  .posts-grid{grid-template-columns:minmax(0,1fr);gap:18px}
  .post-card-content{padding:19px}
  .article-page{padding:24px 20px;border-radius:14px}
  .article-content{font-size:1rem}
  .footer-inner{padding:28px 18px 32px}
}
@media(prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  *,*::before,*::after{transition:none!important;animation:none!important}
}
